import test from "node:test";
import assert from "node:assert/strict";

import { merge } from "../src/merge.js";

test("merging one key keeps the other", () => {
  const base = { server: { host: "a", port: 1 } };
  const out = merge(base, { server: { port: 2 } });
  assert.deepEqual(out, { server: { host: "a", port: 2 } });
});
